import{_ as r,C as d,o as a,c as s,aj as e,E as o}from"./framework.js";const u=JSON.parse('{"title":"Content Entries | Content | Admin CMS","description":"Folder: /_Admin/content/textContentsByFolder?SiteId=...&folder=[contentFolderId]","frontmatter":{"title":"Content Entries | Content | Admin CMS","description":"Folder: /_Admin/content/textContentsByFolder?SiteId=...&folder=[contentFolderId]","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/cms/content/contents-entries.html"}]]},"headers":[],"relativePath":"cms/content/contents-entries.md","filePath":"en/cms/content/contents-entries.md","lastUpdated":1781010536000}'),i={name:"cms/content/contents-entries.md"};function l(c,t,h,g,f,m){const n=d("DocImage");return a(),s("div",null,[t[0]||(t[0]=e('<h1 id="content-entries" tabindex="-1">Content Entries <a class="header-anchor" href="#content-entries" aria-label="Permalink to &quot;Content Entries&quot;">​</a></h1><blockquote><p><strong>Folder</strong>: <code>/_Admin/content/textContentsByFolder?SiteId=...&amp;folder={contentFolderId}</code><br><strong>Edit entry</strong>: <code>/_Admin/content/content?SiteId=...&amp;folder={contentFolderId}&amp;id={entryId}</code> (no <code>id</code> when creating)<br><strong>Single content</strong>: Click the name on the list to open the <code>content</code> route directly; only one entry to maintain</p></blockquote><p>Create and edit concrete data rows under a <a href="./contents-folders-list.html">content folder</a>. Form fields are determined by the folder’s <a href="./content-types.html">content type</a>; if <a href="./contents-folder-settings.html">related data</a> is configured, corresponding sections appear on the edit page (category / embedded selectors).</p><h2 id="how-to-enter" tabindex="-1">How to Enter <a class="header-anchor" href="#how-to-enter" aria-label="Permalink to &quot;How to Enter&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Content folder type</th><th>Action</th></tr></thead><tbody><tr><td><strong>Folder</strong></td><td>Click the content folder <strong>name</strong> on the list → entry list → <strong>New</strong> / row edit</td></tr><tr><td><strong>Single content</strong></td><td>Click <strong>name</strong> on the list → edit that one entry directly (no list page)</td></tr></tbody></table>',5)),o(n,{src:"/cms/content/contents-entry.png",alt:"Entry list inside a folder",width:"1120"}),t[1]||(t[1]=e('<h2 id="entry-list-folder" tabindex="-1">Entry List (Folder) <a class="header-anchor" href="#entry-list-folder" aria-label="Permalink to &quot;Entry List (Folder)&quot;">​</a></h2><p>Common toolbar actions:</p><table tabindex="0"><thead><tr><th>Action</th><th>Description</th></tr></thead><tbody><tr><td><strong>New {display name}</strong></td><td>Create a new content entry</td></tr><tr><td><strong>Export data</strong> / <strong>Import data</strong></td><td>CSV bulk export/import (per UI)</td></tr><tr><td>Search, filter</td><td>If the content type has filterable fields, filters may appear at the top</td></tr><tr><td>Batch delete, etc.</td><td>After selecting rows (when permissions allow)</td></tr></tbody></table><p>List columns typically include identifier, summary field, online status, modified time, etc. (varies by content type and <a href="./contents-folder-settings.html#fields">Content folder settings · Fields</a> order).</p><h2 id="edit-page" tabindex="-1">Edit Page <a class="header-anchor" href="#edit-page" aria-label="Permalink to &quot;Edit Page&quot;">​</a></h2><p>Route <code>content</code>; center area is a dynamic form:</p><ul><li><strong>Content type fields</strong>: text, rich text, image, date, etc.</li><li><strong>Category data</strong>: per aliases in <a href="./contents-folder-settings.html">content folder settings</a>, multi/single select entries from related folders (multi-select when <strong>Multiple</strong> is checked).</li><li><strong>Embedded data</strong>: pick entries from related folders to <strong>embed</strong>, with ordering; grouped embeds show in separate UI sections.</li></ul><p>Bottom bar (common for <strong>folder</strong> type, not single-content folders):</p><table tabindex="0"><thead><tr><th>Button</th><th>Description</th></tr></thead><tbody><tr><td>Save</td><td>Writes the current entry</td></tr><tr><td>Save and return</td><td>Saves then returns to the entry list</td></tr><tr><td>Save and new</td><td>Saves then continues creating the next entry (when creating)</td></tr><tr><td>Save and preview</td><td>Opens the front-end preview URL; multilingual sites can pick language</td></tr></tbody></table>',9)),o(n,{src:"/cms/content/contents-entry-edit.png",alt:"Create/edit content entry",width:"1120"}),t[2]||(t[2]=e('<p><strong>Single content</strong> folders usually only have <strong>Save</strong> / <strong>Cancel</strong>, without list-related buttons like <strong>Save and new</strong>.</p><h2 id="online-status-and-multilingual" tabindex="-1">Online Status and Multilingual <a class="header-anchor" href="#online-status-and-multilingual" aria-label="Permalink to &quot;Online Status and Multilingual&quot;">​</a></h2><ul><li>Whether an entry is <strong>online</strong>, per-language offline state, etc. follow the form and site multilingual settings.</li><li>After <strong>Enable multilingual</strong> on fields in <a href="./content-types.html">content types</a>, the edit page can switch languages for entry.</li></ul><h2 id="using-k-content-after-save" tabindex="-1">Using k.content After Save <a class="header-anchor" href="#using-k-content-after-save" aria-label="Permalink to &quot;Using k.content After Save&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Content folder type</th><th>How to read</th></tr></thead><tbody><tr><td>Folder</td><td><code>k.content.{folderName}.all()</code>, <code>get(id)</code>, <code>find(...)</code>, etc.</td></tr><tr><td>Single content</td><td><code>k.content.{folderName}.fieldName</code> direct access</td></tr><tr><td>Related data</td><td>On <code>get</code> results, access via <a href="./contents-folder-settings.html#reading-related-data-in-kcontent">aliases</a></td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Doc</th><th>Description</th></tr></thead><tbody><tr><td><a href="./contents-folders-list.html">Content folders</a></td><td>Folder vs single content</td></tr><tr><td><a href="./contents-folder-settings.html">Content folder settings</a></td><td>Relations and field order</td></tr><tr><td><a href="/kb-docs/api/content/">k.content</a></td><td>CRUD and query operators</td></tr><tr><td><a href="/kb-docs/templateEngine/k-data/query.html">k-data</a></td><td>Template list binding</td></tr></tbody></table>',7))])}const b=r(i,[["render",l]]);export{u as __pageData,b as default};
